/* ============================================================
   LANGUAGE — Hindi and Gujarati screens.

   The app is written in English. When someone picks हिन्दी or
   ગુજરાતી (More → Language), this file swaps the English words on
   screen for the chosen language as each screen appears.
   - Names, notes and anything people type are left as they are.
   - PDFs, WhatsApp messages and Excel exports stay in English
     (the PDF fonts cannot print these letters).
   - The choice is kept on the phone and in the person's profile,
     so it follows them to a new phone.

   TO CORRECT A TRANSLATION: find the English words in the list
   below and change the Hindi (first) or Gujarati (second) text.
   The English must stay exactly as it is — it is how the app
   finds the words. Please have a native speaker check the lists.
   ============================================================ */
'use strict';

