  'Photos you share from the catalogue or send in a message to shops get this at the bottom right. Empty = your business name. Switch it off below': ['कैटलॉग से शेयर की गई या दुकानों को मैसेज में भेजी गई फोटो के नीचे दाईं ओर यह लिखा जाएगा। खाली = आपके बिज़नेस का नाम। इसे नीचे बंद कर सकते हैं', 'કેટલોગમાંથી શેર કરેલા કે દુકાનોને મેસેજમાં મોકલેલા ફોટામાં નીચે જમણી બાજુ આ લખાશે. ખાલી = તમારા બિઝનેસનું નામ. તેને નીચે બંધ કરી શકો છો'],
  'Shops: picks, designs, ready stock': ['दुकानें: पसंद, डिज़ाइन, रेडी स्टॉक', 'દુકાનો: પસંદગી, ડિઝાઇન, રેડી સ્ટોક'],
  'When a shop picks designs, sends a design it wants made, or chooses from ready stock': ['जब कोई दुकान डिज़ाइन पसंद करे, बनवाने के लिए डिज़ाइन भेजे, या रेडी स्टॉक से चुने', 'જ્યારે કોઈ દુકાન ડિઝાઇન પસંદ કરે, બનાવડાવવા ડિઝાઇન મોકલે, કે રેડી સ્ટોકમાંથી પસંદ કરે'],
  'When your shops pick designs, send a design they want made, or choose from your ready-stock list': ['जब आपकी दुकानें डिज़ाइन पसंद करें, बनवाने के लिए डिज़ाइन भेजें, या आपकी रेडी-स्टॉक सूची से चुनें', 'જ્યારે તમારી દુકાનો ડિઝાઇન પસંદ કરે, બનાવડાવવા ડિઝાઇન મોકલે, કે તમારી રેડી-સ્ટોક યાદીમાંથી પસંદ કરે'],
  'New designs from shops': ['दुकानों से नए डिज़ाइन', 'દુકાનોથી નવી ડિઝાઇન'],
  'Ready-stock choices': ['रेडी-स्टॉक से पसंद', 'રેડી-સ્ટોકમાંથી પસંદગી'],
  'Link for any shop: on': ['किसी भी दुकान के लिए लिंक: चालू', 'કોઈપણ દુકાન માટે લિંક: ચાલુ'],
  'Link for any shop: off': ['किसी भी दुकान के लिए लिंक: बंद', 'કોઈપણ દુકાન માટે લિંક: બંધ'],
  'Put it on your WhatsApp status, Instagram or send it to a new shop — they send photos of a design they want made': ['इसे अपने WhatsApp स्टेटस, Instagram पर लगाएँ या नई दुकान को भेजें — वे जो डिज़ाइन बनवाना चाहते हैं उसकी फोटो भेजते हैं', 'તેને તમારા WhatsApp સ્ટેટસ, Instagram પર મૂકો કે નવી દુકાનને મોકલો — તેઓ જે ડિઝાઇન બનાવડાવવા માંગે છે તેના ફોટા મોકલે છે'],
  'Turn it on to get a link any shop can use to send you photos of a design. Shops with their own page can always send designs from it': ['इसे चालू करें — एक ऐसा लिंक मिलेगा जिससे कोई भी दुकान आपको डिज़ाइन की फोटो भेज सकती है। जिन दुकानों का अपना पेज है, वे उससे हमेशा डिज़ाइन भेज सकती हैं', 'તેને ચાલુ કરો — એવી લિંક મળશે જેનાથી કોઈપણ દુકાન તમને ડિઝાઇનના ફોટા મોકલી શકે. જે દુકાનોનું પોતાનું પેજ છે, તેઓ તેમાંથી હંમેશા ડિઝાઇન મોકલી શકે છે'],
  'The owner can turn on a link any shop can use. Shops with their own page can always send designs from it': ['मालिक ऐसा लिंक चालू कर सकते हैं जो कोई भी दुकान इस्तेमाल कर सके। जिन दुकानों का अपना पेज है, वे उससे हमेशा डिज़ाइन भेज सकती हैं', 'માલિક એવી લિંક ચાલુ કરી શકે છે જે કોઈપણ દુકાન વાપરી શકે. જે દુકાનોનું પોતાનું પેજ છે, તેઓ તેમાંથી હંમેશા ડિઝાઇન મોકલી શકે છે'],
