  'Shops with the link will not be able to send designs from it. Turning it on again makes a new link': ['लिंक वाली दुकानें उससे डिज़ाइन नहीं भेज पाएँगी। फिर से चालू करने पर नया लिंक बनेगा', 'લિંકવાળી દુકાનો તેમાંથી ડિઝાઇન મોકલી શકશે નહીં. ફરી ચાલુ કરવાથી નવી લિંક બનશે'],
