  'Shops buy stock before it — send them your new designs now': ['दुकानें इससे पहले स्टॉक खरीदती हैं — उन्हें अभी अपने नए डिज़ाइन भेजें', 'દુકાનો તેના પહેલાં સ્ટોક ખરીદે છે — તેમને હમણાં તમારી નવી ડિઝાઇન મોકલો'],
