  'Sign out on every phone where you are signed in — this one too. Then sign in again here. For someone in the team: More → Team → their name': ['जिन फोन पर आप साइन इन हैं, उन सब से साइन आउट करें — इस फोन से भी। फिर यहाँ फिर से साइन इन करें। टीम के किसी सदस्य के लिए: मेनू → टीम → उनका नाम', 'જે ફોન પર તમે સાઇન ઇન છો, તે બધામાંથી સાઇન આઉટ કરો — આ ફોનમાંથી પણ. પછી અહીં ફરી સાઇન ઇન કરો. ટીમના કોઈ સભ્ય માટે: મેનુ → ટીમ → તેમનું નામ'],
  'Sign out on every phone where you are signed in — this one too. Then sign in again here. Or ask the owner to do it for you': ['जिन फोन पर आप साइन इन हैं, उन सब से साइन आउट करें — इस फोन से भी। फिर यहाँ फिर से साइन इन करें। या मालिक से कहें', 'જે ફોન પર તમે સાઇન ઇન છો, તે બધામાંથી સાઇન આઉટ કરો — આ ફોનમાંથી પણ. પછી અહીં ફરી સાઇન ઇન કરો. અથવા માલિકને કહો'],
