  'Every phone where this person is signed in is signed out the next time it opens the app. Their data stays in the app': ['जिन फोन पर यह व्यक्ति साइन इन है, वे अगली बार ऐप खुलते ही साइन आउट हो जाएँगे। उनका डेटा ऐप में रहेगा', 'જે ફોન પર આ વ્યક્તિ સાઇન ઇન છે, તે આગલી વાર એપ ખૂલતાં જ સાઇન આઉટ થશે. તેમનો ડેટા એપમાં રહેશે'],
